//		Where(detentioncol.DetentionPolicyColumns.ID.Eq(), id)
func DetentionPolicyScopeTenant(q *bun.SelectQuery, ti pagination.TenantInfo) *bun.SelectQuery {
	return buncolgen.ScopeTenant(q, DetentionPolicyColumns.OrganizationID, DetentionPolicyColumns.BusinessUnitID, ti)
}

